// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u   *repox.Unit
	svc *aperioql.Service
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateSpace queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateSpace(parent string, in *venuepbv1.Space) (string, error) {
	r := &GraphQLSpaceRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueSpaceReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		ops.Add(b.svc.Mutation.Venue.Spaces.CreateOp(ci, new(spacesql.InsertVenueSpacesResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.venue.v1/Space", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateSpace queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateSpace(in *venuepbv1.Space, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "venues", "spaces"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLSpaceRepository{Svc: b.svc}
	queueSpaceReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "aperio.venue.v1/Space", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getSpace)})
}

// DeleteSpace queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) DeleteSpace(name string) {
	if _, err := repox.SplitName(name, "venues", "spaces"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLSpaceRepository{Svc: b.svc}
	queueSpaceDelete(b.u, name, true)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Venue.Spaces.DeleteOp(id, new(spacesql.DeleteVenueSpacesByIdResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.venue.v1/Space", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getSpace)})
}

